360	    private loadNpcSpawns(targetDir?: string) {
361	        if (this.npcsLoaded) return;
362	        try {
363	            // Phase 116: Check public/authentic_spawn_manifest.json for breakthrough tests
364	            const publicSpawns = join(process.cwd(), 'public', 'authentic_spawn_manifest.json');
365	            
366	            const spatialRoot = getAtlasSpatialPath();
367	            const base = targetDir ?? join(spatialRoot, 'npc_extract');
368	            const spawnsPath = join(base, 'npc_spawns.json');
369	            
370	            // Absolute fallback for global NPC truth
371	            const fallbackPath = join(spatialRoot, 'npc_extract', 'npc_spawns.json');
372	            const effectivePath = fs.existsSync(publicSpawns) ? publicSpawns : (fs.existsSync(spawnsPath) ? spawnsPath : fallbackPath);
373	
374	            if (fs.existsSync(effectivePath)) {
375	                const data = fs.readFileSync(effectivePath, 'utf8');
376	                const parsed = JSON.parse(data);
377	                // Support both raw array and { entities: [...] } manifest formats
378	                this.npcSpawns = Array.isArray(parsed) ? parsed : (Array.isArray(parsed.entities) ? parsed.entities : []);
379	                this.npcsLoaded = true;
380	                logger.debug({ count: this.npcSpawns.length, source: effectivePath }, 'NPC Spawns grounded via Breakthrough Manifest.');
381	            }
382	        } catch (err) {
383	            logger.warn('NPC Spawns database unavailable.');
384	        }
385	    }
