387	    public async manifestNearbyEntities(chunkX: number, chunkZ: number): Promise<void> {
388	        this.loadNpcSpawns();
389	        const minX = chunkX << 6;
390	        const minZ = chunkZ << 6;
391	        const maxX = minX + 63;
392	        const maxZ = minZ + 63;
393	
394	        const localSpawns = this.npcSpawns.filter(s => {
395	            const x = s.worldX ?? s.coord?.x;
396	            const z = s.worldZ ?? s.coord?.z ?? s.coord?.y;
397	            return x >= minX && x <= maxX && z >= minZ && z <= maxZ;
398	        });
399	        if (localSpawns.length === 0) return;
400	
401	        const tx = this.beginTick();
402	        const spatial = SpatialSovereigntyLimb.getInstance();
403	
404	        for (const spawn of localSpawns) {
405	            const x = spawn.worldX ?? spawn.coord?.x;
406	            const z = spawn.worldZ ?? spawn.coord?.z ?? spawn.coord?.y;
407	            const plane = spawn.plane ?? spawn.coord?.plane ?? 0;
408	            const npcId = spawn.npcId ?? spawn.entityId;
409	            const npcName = spawn.npcName ?? spawn.title ?? `Entity ${npcId}`;
410	
411	            const entId = `npc_${npcId}_${x}_${z}`;
412	            if (this.manifest.entities[entId]) continue;
413	            tx.set(entId, {
414	                id: entId,
415	                npcId: npcId,
416	                name: npcName,
417	                spatial: { x: x, y: z, z: spatial.getAltitude(plane, x, z), plane: plane },
418	                behavior: 'STATIC_FORENSIC'
419	            });
420	        }
421	        await this.commitTick(tx);
422	    }
